const drugClassSpend = {
  "GLP-1": { spend: 8689247156, perRx: 1063 },
  "Metformin": { spend: 126154617, perRx: 12.90 },
  "Insulin": { spend: 1152774328, perRx: 170 },
  "DPP-4": { spend: 946748333, perRx: 754 }
};

function classify(name) {
  const n = (name || "").toUpperCase();
  if (/OZEMPIC|WEGOVY|MOUNJARO|ZEPBOUND|TRULICITY|RYBELSUS|VICTOZA|SEMAGLUTIDE|TIRZEPATIDE|DULAGLUTIDE|LIRAGLUTIDE/.test(n)) return "GLP-1";
  if (/METFORMIN|GLUCOPHAGE/.test(n)) return "Metformin";
  if (/JANUVIA|JANUMET|TRADJENTA|ONGLYZA|SITAGLIPTIN|LINAGLIPTIN|SAXAGLIPTIN/.test(n)) return "DPP-4";
  if (/INSULIN|LANTUS|HUMALOG|NOVOLOG|TRESIBA|LEVEMIR/.test(n)) return "Insulin";
  return null;
}

const records = $input.first().json.results || [];
const briefingRows = [];
for (const r of records) {
  const brand = (r.openfda && r.openfda.brand_name && r.openfda.brand_name[0]) || "Unknown";
  const cls = classify(brand);
  if (!cls) continue;
  briefingRows.push({ drug_class: cls, classification: r.classification || "Unknown", spend: drugClassSpend[cls].spend });
}

// Roll up per class
const classRollup = {};
for (const row of briefingRows) {
  if (!classRollup[row.drug_class]) classRollup[row.drug_class] = { count: 0, spend: row.spend, severities: new Set() };
  classRollup[row.drug_class].count++;
  classRollup[row.drug_class].severities.add(row.classification);
}

// Fact block for the LLM (so it can reference context, but it only writes an intro)
let factBlock = `Total recalls: ${briefingRows.length}. Classes affected: `;
factBlock += Object.keys(classRollup).map(c => `${c} (${classRollup[c].count} recalls)`).join(", ") + ".";

// Pre-build the data table rows (CODE owns every number)
const sevColor = (sevs) => sevs.includes("Class I") ? "#ff6b9d" : sevs.includes("Class II") ? "#ffa45c" : "#7dd3a0";
let tableRows = "";
for (const cls of Object.keys(classRollup)) {
  const c = classRollup[cls];
  const sevs = [...c.severities];
  tableRows += `<tr>
    <td style="padding:14px 18px;border-bottom:1px solid #f0e6f0;font-weight:600;color:#6b4c7a;">${cls}</td>
    <td style="padding:14px 18px;border-bottom:1px solid #f0e6f0;text-align:center;color:#9a7bab;">${c.count}</td>
    <td style="padding:14px 18px;border-bottom:1px solid #f0e6f0;text-align:center;"><span style="background:${sevColor(sevs)};color:#fff;padding:4px 12px;border-radius:20px;font-size:11px;font-weight:600;">${sevs.join(", ")}</span></td>
    <td style="padding:14px 18px;border-bottom:1px solid #f0e6f0;text-align:right;font-weight:700;color:#6b4c7a;">$${(c.spend/1e9).toFixed(2)}B</td>
  </tr>`;
}

return [{ json: { factBlock, tableRows, totalRecalls: briefingRows.length } }];
